for x in ideas:
 x['scoreIntervals']={k:[max(0,v-1),min(4,v+1)] for k,v in x['scores'].items()}
 x['queueEligible']=x['scores']['specification']>=3 and x['scores']['discrimination']>=3 and x['scores']['tractability']>=2
 x['niche']=x['scope']+' / '+x['intervention']
 x['noveltyConfidence']='provisional; no exhaustive literature search'
 x['literatureRefs']={'I03':['WB'],'I06':['QDHF'],'I08':['ALLOSTERY'],'I14':['ASAL'],'I15':['IPC'],'I17':['RESDMD'],'I18':['TC'],'I24':['SHEAF']}.get(x['id'],[])
def dominates(a,b):return all(a[k]>=b[k] for k in a) and any(a[k]>b[k] for k in a)
for x in ideas:
 peers=[p for p in ideas if p['niche']==x['niche'] and p['queueEligible']]
 x['dominatedBy']=[p['id'] for p in peers if p['id']!=x['id'] and dominates(p['scores'],x['scores'])]
 x['nominalNicheFrontier']=x['queueEligible'] and not x['dominatedBy']
 x['robustlyDominatedBy']=[p['id'] for p in peers if p['id']!=x['id'] and dominates({k:v[0] for k,v in p['scoreIntervals'].items()},{k:v[1] for k,v in x['scoreIntervals'].items()})]
